import math


def gradient(weights, x, y):
    if not x:
        return [0.0] * len(weights)
    errors = [sum(a * b for a, b in zip(row, weights)) - target
              for row, target in zip(x, y)]
    return [2.0 * (sum(error * row[j] for error, row in zip(errors, x)) / len(x))
            for j in range(len(weights))]


def step(weights, velocity, g, lr, momentum, clip):
    if clip < 0:
        raise ValueError('clip')
    if clip == 0:
        clipped = [0.0] * len(g)
    else:
        norm = math.hypot(*g)
        scale = min(1.0, clip / norm) if norm else 1.0
        clipped = [d * scale for d in g]
    new_velocity = [momentum * v + d for v, d in zip(velocity, clipped)]
    return [w - lr * v for w, v in zip(weights, new_velocity)], new_velocity

from core import gradient, step


def solve(p):
    if p['clip'] < 0:
        raise ValueError('clip')
    w = list(p['weights'])
    v = list(p['velocity'])
    for batches in p['steps']:
        total = sum(len(batch['x']) for batch in batches)
        if not total:
            continue
        g = [0.0] * len(w)
        for batch in batches:
            count = len(batch['x'])
            if not count:
                continue
            part = gradient(w, batch['x'], batch['y'])
            fraction = count / total
            g = [a + b * fraction for a, b in zip(g, part)]
        w, v = step(w, v, g, p['lr'], p['momentum'], p['clip'])
    return {'weights': w, 'velocity': v}
